def balanced(s: str) -> bool:
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

def merge(a: list, b: list) -> list:
    result = []
    i, j = 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

def top_word(text: str) -> str:
    words = text.split()
    if not words:
        return ""
    counts = {}
    first_seen = {}
    for i, w in enumerate(words):
        lw = w.lower()
        counts[lw] = counts.get(lw, 0) + 1
        if lw not in first_seen:
            first_seen[lw] = i
    max_count = max(counts.values())
    # Find the word with max_count that has the smallest first_seen index
    result = min((w for w in counts if counts[w] == max_count), key=lambda w: first_seen[w])
    return result

def to_base(n: int, b: int) -> str:
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    result = []
    while n > 0:
        result.append(digits[n % b])
        n //= b
    return ''.join(reversed(result))
